import React, { useState } from 'react';
import useMarvelApi from '../hooks/useMarvelApi';
// import useIMDBData from '../hooks/useIMDBData'; // Commented out for now, as it's not used in the provided snippet
import Comic from '../components/Comic';
// import Movies from '../components/Movies'; // Commented out as it's not part of the provided snippet
import '../styles/searchPage.css';

function Search() {
  const [query, setQuery] = useState('');
  const [searchTerm, setSearchTerm] = useState(''); // To store the actual query to be searched
  const { data, loading, error } = useMarvelApi(searchTerm); // Changed to use searchTerm

  // Handler for when the search button is clicked
  const handleSearchClick = () => {
    setSearchTerm(query); // Sets searchTerm which triggers the API call
  };

  return (
    <section id="search-section">
      <h1>Search Marvel Characters</h1>
      <div className="search-container">
        <input
          type="text"
          placeholder="Enter character name"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <button onClick={handleSearchClick}>Search</button>
      </div>

      {/* <Movies /> */}

      {loading && <div>Loading...</div>}
      {error && <div>Error: {error.message}</div>}
      <h2>Comic Books</h2>
      {data && <Comic characters={data} />}
    </section>
  );
}

export default Search;
